ukrFunction**** allocateMatrix() {
    ukrFunction**** matrix = (ukrFunction****)malloc(129 * sizeof(ukrFunction***));
    for (int i = 0; i < 129; i++) {
        matrix[i] = (ukrFunction***)malloc(129 * sizeof(ukrFunction**));
        for (int j = 0; j < 129; j++) {
            matrix[i][j] = (ukrFunction**)malloc(2 * sizeof(ukrFunction*));
            for (int b = 0; b < 2; b++) {
                matrix[i][j][b] = (ukrFunction*)malloc(1 * sizeof(ukrFunction));
            }
        }
    }
    return matrix;
}


